"Optional · selected task evidence is sent to TypeSafe when you run. Provider usage charges apply. PandaCode works without Jev. Advice does not change files, models, or permissions.": "Opcjonalne · przy uruchomieniu wybrane dowody zadania są wysyłane do TypeSafe. Obowiązują opłaty za użycie dostawcy. PandaCode działa bez Jev. Porady nie zmieniają plików, modeli ani uprawnień.",
