"Optional. Tone, values and conversational style, kept apart from the instructions. Importing copies the file once; later changes to the file do not change the bot. Personality never grants tools or permissions.": "Opcjonalne. Ton, wartości i styl rozmowy, trzymane osobno od instrukcji. Import kopiuje plik raz; późniejsze zmiany pliku nie zmieniają bota. Osobowość nigdy nie nadaje narzędzi ani uprawnień.",
