"PandaCode has no “{0}” view. Showing its data instead.": "PandaCode nie ma widoku \"{0}\". Pokazuję zamiast tego jego dane.",
"PandaCode quick launcher": "Szybki program uruchamiający PandaCode",
"PandaCode restarts when your agents are done and you step away.": "PandaCode uruchomi się ponownie, gdy agenty skończą i Ty odejdziesz.",
"PandaCode runs Linux and macOS VMs on Apple's Virtualization framework: headless, and only the memory you give it.": "PandaCode uruchamia maszyny wirtualne Linux i macOS na frameworku Virtualization Apple: bez interfejsu i tylko z pamięcią, którą przyznasz.",
"PandaCode tools": "Narzędzia PandaCode",
"PandaCode uses it to check that messages really come from Meta.": "PandaCode używa tego, aby sprawdzać, czy wiadomości naprawdę pochodzą od Meta.",
"PandaCode will restart to update when your agents finish.": "Gdy agenty skończą, PandaCode uruchomi się ponownie, aby się zaktualizować.",
"PandaCode works without Jev or a TypeSafe key. Optional decision assistance only needs the key for the provider you pick. OpenRouter models are listed only when you open the model menu. Keys are saved privately on this device, outside the keychain. Leave a field empty to keep its saved key.": "PandaCode działa bez Jev i bez klucza TypeSafe. Opcjonalna asysta decyzyjna potrzebuje klucza tylko wybranego dostawcy. Modele OpenRouter pojawiają się dopiero po otwarciu menu modeli. Klucze zapisują się prywatnie na tym urządzeniu, poza keychainem. Zostaw pole puste, aby zachować jego zapisany klucz.",
