"Use Copilot Agent mode with Allow All on. Copilot automatically approves tool, path, and URL requests.": "Użyj trybu Copilot Agent z włączonym Allow All. Copilot automatycznie zatwierdza prośby o narzędzia, ścieżki i adresy URL.",
"Use Copilot Plan mode. Read, search, fetch, and think requests are allowed; other permission requests are declined.": "Użyj trybu Copilot Plan. Prośby o czytanie, wyszukiwanie, pobieranie i myślenie są zezwalane; pozostałe prośby o uprawnienia są odrzucane.",
