"That does not look like an AWS region (for example us-east-1).": "To nie wygląda na region AWS (np. us-east-1).",
"That doesn't look like a Discord bot token. In the Developer Portal open Bot → Reset Token and copy the whole value. (The Client Secret and Public Key are different values.)": "To nie wygląda na token bota Discord. W Developer Portal otwórz Bot → Reset Token i skopiuj całą wartość. (Client Secret i Public Key to inne wartości.)",
"That doesn't look like a Telegram bot token. It looks like 123456789:AAE… — copy the whole line BotFather sent.": "To nie wygląda na token bota Telegram. Wygląda jak 123456789:AAE…; skopiuj cały wiersz wysłany przez BotFather.",
