"The app-level token starts with xapp-. Create it under Basic Information → App-Level Tokens with the connections:write scope.": "Token na poziomie aplikacji zaczyna się od xapp-. Utwórz go w Basic Information → App-Level Tokens z zakresem connections:write.",
"The bot token starts with xoxb-. Find it under OAuth & Permissions → Bot User OAuth Token (install the app first).": "Token bota zaczyna się od xoxb-. Znajdziesz go w OAuth & Permissions → Bot User OAuth Token (najpierw zainstaluj aplikację).",
