"The selected Claude model does not support this reasoning effort. Choose another effort or use harness settings.": "Wybrany model Claude nie obsługuje tego poziomu rozumowania. Wybierz inny poziom albo użyj ustawień agenta.",
"The selected Codex model does not support this reasoning effort. Choose another effort or use harness settings.": "Wybrany model Codex nie obsługuje tego poziomu rozumowania. Wybierz inny poziom albo użyj ustawień agenta.",
"The selected model was not found in the current Codex catalog. Refresh models.": "Wybranego modelu nie ma w bieżącym katalogu Codex. Odśwież modele.",
"The selected profile does not match this team setup. Save it as a custom setup or update the profile first.": "Wybrany profil nie pasuje do tej konfiguracji zespołu. Zapisz ją jako konfigurację własną albo najpierw zaktualizuj profil.",
"The sign-in code expired. Start again.": "Kod logowania wygasł. Zacznij od nowa.",
"The simulator tools returned an unexpected response.": "Narzędzia symulatora zwróciły nieoczekiwaną odpowiedź.",
"The source setup changed. Refresh the import preview before importing.": "Konfiguracja źródła się zmieniła. Odśwież podgląd importu przed importem.",
"The source task changed projects. Open its commands again.": "Zadanie źródłowe zmieniło projekt. Otwórz jego polecenia ponownie.",
"The task changed while commands were loading. Try again.": "Zadanie zmieniło się podczas wczytywania poleceń. Spróbuj ponownie.",
"The task command changed. Try again to load its commands.": "Polecenie zadania się zmieniło. Spróbuj ponownie wczytać jego polecenia.",
"The task moved projects during the check. Prepare its evidence again.": "Zadanie zmieniło projekt w trakcie sprawdzenia. Przygotuj jego dowody ponownie.",
