"The task's model changed. Open its settings again.": "Model zadania się zmienił. Otwórz jego ustawienia ponownie.",
"The team changed. Review the task again before deleting it.": "Zespół się zmienił. Przejrzyj zadanie ponownie przed usunięciem.",
"The theme includes too many files.": "Ten motyw zawiera za dużo plików.",
"The two Slack tokens are swapped: the bot token starts with xoxb-, the app-level token with xapp-.": "Dwa tokeny Slack są zamienione miejscami: token bota zaczyna się od xoxb-, a token na poziomie aplikacji od xapp-.",
"The worker checkout no longer matches its architect.": "Kopia robocza workera nie pasuje już do swojego Architekta.",
"The worktree folder already exists.": "Folder drzewa roboczego już istnieje.",
"The worktree folder is missing; recreate it first.": "Brakuje folderu drzewa roboczego; najpierw go odtwórz.",
"The worktree has uncommitted changes. Commit or discard them first; only committed work is merged.": "Drzewo robocze ma niezacommitowane zmiany. Najpierw je zacommituj lub odrzuć; scalana jest tylko zacommitowana praca.",
"The worktree is not on a branch, so there is nothing to merge.": "Drzewo robocze nie jest na gałęzi, więc nie ma czego scalać.",
"This ACP server cannot resume saved tasks. Update the server or start a new task.": "Ten serwer ACP nie może wznawiać zapisanych zadań. Zaktualizuj serwer albo zacznij nowe zadanie.",
"This CodeSandbox VM only offers the Pitcher WebSocket protocol, which PandaCode can't run commands through yet.": "Ta maszyna wirtualna CodeSandbox oferuje tylko protokół Pitcher WebSocket, przez który PandaCode nie potrafi jeszcze uruchamiać poleceń.",
"This Codex conversation belongs to a different project.": "Ta rozmowa Codex należy do innego projektu.",
"This Codex operation is not available on the running task.": "Ta operacja Codex nie jest dostępna na działającym zadaniu.",
"This Codex setting cannot be changed here.": "Tego ustawienia Codex nie można tu zmienić.",
"This Codex version predates the verified native update command. Use the official installation guide.": "Ta wersja Codex jest starsza niż zweryfikowane natywne polecenie aktualizacji. Użyj oficjalnego przewodnika instalacji.",
"This Devin model does not accept images. Choose another model, or remove the images and describe them.": "Ten model Devin nie przyjmuje obrazów. Wybierz inny model albo usuń obrazy i opisz je słowami.",
"This Devin version does not support ACP protocol v1. Update Devin.": "Ta wersja Devin nie obsługuje protokołu ACP v1. Zaktualizuj Devin.",
"This E2B sandbox is paused. Start it first.": "Ta piaskownica E2B jest wstrzymana. Najpierw ją uruchom.",
"This Kimi installation could not be matched to the native or Python release line. Follow its official installation guide.": "Tej instalacji Kimi nie da się dopasować do linii wydań natywnej albo Python. Zastosuj jej oficjalny przewodnik instalacji.",
"This Kimi model does not advertise the selected thinking setting. Choose another setting or use harness settings.": "Ten model Kimi nie ogłasza wybranego ustawienia myślenia. Wybierz inne albo użyj ustawień agenta.",
"This Kimi version does not support a verified unattended upgrade. Update it once using the official installation guide.": "Ta wersja Kimi nie obsługuje zweryfikowanej aktualizacji bez nadzoru. Zaktualizuj ją raz według oficjalnego przewodnika instalacji.",
"This Kimi version does not support screenshot input. Update Kimi Code or remove the screenshots.": "Ta wersja Kimi nie obsługuje wejścia ze zrzutów ekranu. Zaktualizuj Kimi Code albo usuń zrzuty.",
"This Kimi version does not support the HTTP MCP transport required by architect teams. Update Kimi Code.": "Ta wersja Kimi nie obsługuje transportu HTTP MCP wymaganego przez zespoły Architekta. Zaktualizuj Kimi Code.",
"This Muse Code version cannot attach PandaCode's agent tools. Update Muse Code and retry.": "Ta wersja Muse Code nie może dołączyć narzędzi agentów PandaCode. Zaktualizuj Muse Code i ponów.",
"This OpenCode major version uses a different release feed. Use its official installation guide.": "Ta wersja główna OpenCode używa innego źródła wydań. Użyj oficjalnego przewodnika instalacji.",
"This OpenCode major version uses a different updater. Use its official installation guide.": "Ta wersja główna OpenCode używa innego mechanizmu aktualizacji. Użyj oficjalnego przewodnika instalacji.",
"This VM has no Tart Guest Agent, so commands cannot run in it. Use a Cirrus Labs base image.": "Ta maszyna wirtualna nie ma Tart Guest Agent, więc polecenia nie mogą w niej działać. Użyj obrazu bazowego Cirrus Labs.",
"This agent cannot be steered; the message stays queued.": "Nie da się sterować tym agentem; wiadomość pozostaje w kolejce.",
"This agent uses a custom installation directory. Use its official updater to preserve that configuration.": "Ten agent używa własnego katalogu instalacji. Użyj jego oficjalnego mechanizmu aktualizacji, aby zachować tę konfigurację.",
"This approval is no longer pending.": "To zatwierdzenie już nie oczekuje.",
"This attachment is no longer on this computer.": "Ten załącznik nie jest już na tym komputerze.",
"This batch launcher is unsupported. Select the native harness executable instead.": "Ten program uruchamiający partii jest nieobsługiwany. Wybierz zamiast tego natywny plik wykonywalny agenta.",
"This bot is paused.": "Ten Bot jest wstrzymany.",
"This browser test belongs to a different task.": "Ten test przeglądarki należy do innego zadania.",
"This cloud run can't be reached any more.": "Tego uruchomienia chmurowego nie da się już osiągnąć.",
