"PandaCode manages Netlify credentials and telemetry; authentication overrides, debug logging and telemetry enabling are not available.": "PandaCode zarządza danymi logowania Netlify i telemetrią; nadpisania uwierzytelniania, logowanie debugowania i włączanie telemetrii są niedostępne.",
"Netlify builds are not available with the connected token. Build locally first; PandaCode deploys with --no-build.": "Buildy Netlify nie są dostępne z podłączonym tokenem. Najpierw zbuduj lokalnie; PandaCode wdraża z --no-build.",
"That Netlify command is not available here. Use deploy, status, sites:list, sites:create, link or environment writes.": "To polecenie Netlify nie jest tu dostępne. Używaj deploy, status, sites:list, sites:create, link albo zapisów środowiska.",
