"No Ubuntu 24.04 image in this Vultr account's OS list; pick another provider or check vultr.com.": "Brak obrazu Ubuntu 24.04 na liście systemów tego konta Vultr; wybierz innego dostawcę albo sprawdź vultr.com.",
