"The saved environment variables are too large to send to a cloud machine. Remove a few in Settings → Providers and start the task again.": "Zapisane zmienne środowiskowe są zbyt duże, aby wysłać je na maszynę chmurową. Usuń kilka w Ustawienia → Dostawcy i uruchom zadanie ponownie.",
